variables { message EngineData msg; msTimer t; }
on start { setTimer(t, 100); }
on timer t {
  msg.EngineSpeed = 2500;
  output(msg);
  setTimer(t, 100);
}

testcase TC_DTC_P0300() {
  testCaseTitle("DTC P0300 sets on misfire");
  // Stimulate fault
  sysSetVariable(sysvar::FaultInject, 1);
  // Wait for DTC
  testWaitForSignalInRange(
    EngineControl::DTC_P0300, 1,1, 2000);
  testStep("DTC confirmed", testGetLastResult());
}

