on message EngineData {
  if (this.EngineSpeed > 7000) {
    write("Overspeed! %.0f rpm",
      this.EngineSpeed);
  }
}
on signal BatteryVoltage {
  if (BatteryVoltage < 9.0)
    write("Low voltage alert");
}
